package com.flippingfriend.companion;
import java.util.ArrayList; import java.util.List;
/** Pure fail-closed application of CandidateFactory fractional-Kelly arithmetic. */
final class BuyReplacementKellyFractionEvaluator {
 BuyReplacementKellyFractionEvaluationSet evaluate(BuyReplacementKellySizingInputContext s,long at){if(s==null||at<s.getComposedAt()||s.getComposedAt()+CompanionBuyReplacementReadinessPolicy.MAX_INPUT_AGE_SECONDS<at||s.getInputs()==null||s.getInputs().isEmpty()||!Double.isFinite(s.getKellyShare())||s.getKellyShare()<=0||!Double.isFinite(s.getMinimumKellyFraction())||s.getMinimumKellyFraction()<=0||s.getMinimumKellyFraction()>1)return null;List<BuyReplacementKellyFractionEvaluation> out=new ArrayList<>(s.getInputs().size());for(BuyReplacementKellySizingInput i:s.getInputs()){if(!valid(i,s))return null;double p=i.getCompletionProbability();double b=i.getPayoffOdds();double fraction=b<=0||p<=0?s.getMinimumKellyFraction():Math.max(s.getMinimumKellyFraction(),Math.min(1.0,s.getKellyShare()*((p*b-(1.0-p))/b)));if(!Double.isFinite(fraction)||fraction<s.getMinimumKellyFraction()||fraction>1)return null;out.add(new BuyReplacementKellyFractionEvaluation(i,fraction));}return new BuyReplacementKellyFractionEvaluationSet(s,out,at);}
 private static boolean valid(BuyReplacementKellySizingInput i,BuyReplacementKellySizingInputContext s){return i!=null&&i.getFillableQuantity()==s.getExactRemainderQuantity()&&i.getBuyPrice()>0&&i.getSellPrice()>0&&i.getFullNetProfit()>0&&i.getFullUnwindLoss()>=0&&Double.isFinite(i.getCompletionProbability())&&i.getCompletionProbability()>0&&i.getCompletionProbability()<=1&&Double.isFinite(i.getPayoffOdds())&&i.getPayoffOdds()>0;}
}
